"""Seat a class in rows, sorted by last name."""

from typing import Iterable, List

from rosterkit.models import Student


def last_name_of(student: Student) -> str:
    return student.last_name


def check_seating(
    roster: List[Student], seats_per_row: int
) -> None:
    """Refuse an empty class or a row with no seats."""
    if seats_per_row <= 0:
        raise ValueError(f"bad seat count: {seats_per_row}")
    if not roster:
        raise ValueError("no students to seat")


def chunked(
    items: List[Student], size: int
) -> List[List[Student]]:
    """Consecutive slices, each at most size long."""
    starts = range(0, len(items), size)
    return [items[start:start + size] for start in starts]


def format_row(number: int, seated: List[Student]) -> str:
    names = " | ".join(item.display_name for item in seated)
    return f"Row {number}: {names}"


def format_rows(rows: List[List[Student]]) -> List[str]:
    """One formatted line per row, numbered from one."""
    lines = []
    for number, seated in enumerate(rows, 1):
        lines.append(format_row(number, seated))
    return lines


def seat_rows(
    students: Iterable[Student], seats_per_row: int
) -> List[str]:
    """One line per row, students sorted by last name."""
    roster = sorted(students, key=last_name_of)
    check_seating(roster, seats_per_row)
    return format_rows(chunked(roster, seats_per_row))
